function parseCsv(raw:string):string[][]{const rows:string[][]=[];let row:string[]=[],cell='',quoted=false;for(let n=0;n<raw.length;n++){const c=raw[n];if(c==='"'){if(quoted&&raw[n+1]==='"'){cell+='"';n++}else quoted=!quoted}else if(c===','&&!quoted){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&raw[n+1]==='\n')n++;row.push(cell);if(row.some(x=>x!==''))rows.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x!==''))rows.push(row);return rows}
function normalDate(raw:string):string|null{const value=raw.trim();if(/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const m=value.match(/^(\d{1,2})[\/\-.](\d{1,2})[\/\-.](\d{4})$/);if(m){const day=Number(m[1]),month=Number(m[2]),year=Number(m[3]);const d=new Date(Date.UTC(year,month-1,day));if(d.getUTCFullYear()===year&&d.getUTCMonth()===month-1&&d.getUTCDate()===day)return `${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`}return null}
const statementAmount=(raw:string)=>{const value=raw.replace(/,/g,'').replace(/[₹\s]/g,'');const n=Number(value);return Number.isFinite(n)?n:null}
function statementDate(raw:string):string|null{const value=raw.trim();const numeric=normalDate(value);if(numeric)return numeric;const m=value.match(/^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$/);if(!m)return null;const month=['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(m[2].slice(0,3).toLowerCase());if(month<0)return null;return `${m[3]}-${String(month+1).padStart(2,'0')}-${String(Number(m[1])).padStart(2,'0')}`}
const statementMoneyPattern=/(?:\d{1,3}(?:,\d{2,3})+|\d+)\.\d{2}/g
function parseBankStatement(raw:string):{bank:string;rows:string[][];start:string;end:string;opening:string;closing:string}|null{
 const kotak=/Current Account Transactions[\s\S]*Withdrawal\s*\(Dr\.\)[\s\S]*Deposit\s*\(Cr\.\)/i.test(raw)&&/Account Statement/i.test(raw)
 const rbl=/Transactions List\s*-\s*CAEXB/i.test(raw)&&/Statement Summary/i.test(raw)
 if(!kotak&&!rbl)return null
 const lines=raw.split(/\r?\n/).map(x=>x.trim()).filter(Boolean)
 const startEnd=kotak?raw.match(/(\d{1,2}\s+[A-Za-z]{3}\s+\d{4})\s*-\s*(\d{1,2}\s+[A-Za-z]{3}\s+\d{4})/i):raw.match(/Period:\s*(\d{1,2}\/\d{1,2}\/\d{4})\s+to\s+(\d{1,2}\/\d{1,2}\/\d{4})/i)
 const start=startEnd?statementDate(startEnd[1]):null,end=startEnd?statementDate(startEnd[2]):null
 const openingMatch=kotak?raw.match(/Opening Balance[\s\S]{0,80}?([\d,]+\.\d{2})/i):raw.match(/Opening Balance:\s*(?:₹\s*)?([\d,]+\.\d{2})/i)
 const closingMatch=kotak?null:raw.match(/Closing Balance:\s*(?:₹\s*)?([\d,]+\.\d{2})/i)
 const opening=openingMatch?statementAmount(openingMatch[1]):null
 let blocks:{date:string;text:string}[]=[];let current:{date:string;text:string}|null=null
 const isNoise=(line:string)=>/^(Account Statement|Current Account Transactions|Statement Of Transactions|Transactions List|Statement Summary|#\s+Date|Date and Time:|ATIF FAKHRUDDIN|Account No\.|Period:|-\s*-\s*Opening Balance|Statement Generated on|Page \d+ of \d+)/i.test(line)
 for(const line of lines){
  const m=kotak?line.match(/^(\d{1,3})\s+(\d{1,2}\s+[A-Za-z]{3}\s+\d{4})\s+(.+)$/i):line.match(/^(\d{1,2}\/\d{1,2}\/\d{4})\s+(.+)$/)
  if(m){if(current)blocks.push(current);current={date:kotak?m[2]:m[1],text:m[kotak?3:2]};continue}
  if(current&&!isNoise(line)&&!(/Opening Balance/i.test(line)))current.text+=` ${line}`
 }
 if(current)blocks.push(current)
 const parsed=blocks.map((block,index)=>{const date=statementDate(block.date);const amounts=[...block.text.matchAll(statementMoneyPattern)].map(m=>statementAmount(m[0])).filter((x):x is number=>x!==null);const balance=amounts.at(-1);const description=block.text.replace(statementMoneyPattern,' ').replace(/\b\d{1,2}\/\d{1,2}\/\d{4}\b/g,' ').replace(/\s+/g,' ').trim();return {date,balance,description,index}}).filter(x=>x.date&&x.balance!==undefined)
 if(!parsed.length||opening===null||!start||!end)return null
 const ascending=parsed.slice().reverse()
 const rows=ascending.map((row,index)=>{const previous=index===0?opening:ascending[index-1].balance!;const signed=(row.balance!-previous);return [row.date!,row.description||'Bank transaction',signed.toFixed(2),row.balance!.toFixed(2)]})
 const closing=closingMatch?statementAmount(closingMatch[1]):parsed[0].balance!
 if(closing===null)return null
 return {bank:kotak?'Kotak Bank':'RBL Bank',rows,start,end,opening:opening.toFixed(2),closing:closing.toFixed(2)}
}
function signedMinor(raw:string):number|null{const marked=raw.trim().match(/^(.*?)\s*\(?\s*(Dr|Cr)\s*\)?$/i);const value=(marked?marked[1]:raw).trim().replace(/,/g,'').replace(/[₹$]/g,'');if(!/^-?\d+(\.\d{1,2})?$/.test(value))return null;const sign=marked?(marked[2].toLowerCase()==='dr'?-1:1):(value.startsWith('-')?-1:1);const [whole,part='']=value.replace('-','').split('.');const result=sign*(Number(whole)*100+Number(part.padEnd(2,'0')));return Number.isSafeInteger(result)?result:null}
